'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var pdf = require( './../lib' );


// FIXTURES //

var data = require( './fixtures/python/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof pdf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', function test( t ) {
	var y;

	y = pdf( NaN, 0.0, 1.0, -1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5, NaN, 1.0, -1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5, 0.0, NaN, -1.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5, 0.0, 1.0, NaN, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5, 0.0, 1.0, -1.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a non-positive `sigma`, the function returns `NaN`', function test( t ) {
	var y;

	y = pdf( 0.5, 0.0, 1.0, -1.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5, 0.0, 1.0, -1.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided `a >= b`, the function returns `NaN`', function test( t ) {
	var y;

	y = pdf( 0.5, 1.0, 1.0, 0.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = pdf( 0.5, 2.0, 1.0, 0.0, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `0` if provided `x` outside `[a, b]`', function test( t ) {
	var y;

	y = pdf( -2.0, 0.0, 1.0, 0.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = pdf( 2.0, 0.0, 1.0, 0.0, 1.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the PDF', function test( t ) {
	var expected;
	var sigma;
	var mu;
	var a;
	var b;
	var x;
	var y;
	var i;

	x = data.x;
	mu = data.mu;
	sigma = data.sigma;
	a = data.a;
	b = data.b;
	expected = data.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = pdf( x[ i ], a[ i ], b[ i ], mu[ i ], sigma[ i ] );
		if ( y === expected[ i ] ) {
			t.strictEqual( y, expected[ i ], 'returns expected value' );
		} else {
			t.strictEqual( isAlmostSameValue( y, expected[ i ], 22 ), true, 'returns expected value' );
		}
	}
	t.end();
});
